// Builds the "All apps" catalogue (category filters + cards) in index.html, fr/index.html and ar/index.html.
// Edit CATEGORIES / APPS below, then run:  node tools/catalog.js
// The block between <!-- catalog:start --> and <!-- catalog:end --> is regenerated; do not edit it by hand.
const fs = require('fs');
const path = require('path');
const ROOT = path.join(__dirname, '..');

const CATEGORIES = [
  { id: 'all', en: 'All', fr: 'Toutes', ar: 'الكل' },
  { id: 'spirituality', en: 'Spirituality', fr: 'Spiritualité', ar: 'روحانيات' },
  { id: 'games', en: 'Games', fr: 'Jeux', ar: 'ألعاب' },
  { id: 'health', en: 'Health', fr: 'Santé', ar: 'الصحة' },
  { id: 'tools', en: 'Tools', fr: 'Outils', ar: 'أدوات' },
  { id: 'family', en: 'Family & safety', fr: 'Famille et sécurité', ar: 'الأسرة والأمان' },
  { id: 'love', en: 'Love & couples', fr: 'Rencontres et couple', ar: 'التعارف والأزواج' },
  { id: 'finance', en: 'Finance', fr: 'Finances', ar: 'المال' },
];

// live: true → links to its page and shows a screenshot. Otherwise shown as "Coming soon".
// page: path of the app page; localized: true if /fr/ and /ar/ versions exist.
// icon: image path, or mono: a letter when the app has no final icon yet. color: glow of "soon" cards.
const APPS = [
  { id: 'athkar360', name: 'Athkar 360', cat: 'spirituality', live: true, page: '/athkar360/', localized: true,
    shot: '/athkar360/img/home-dark.webp', icon: '/athkar360/img/icon-256.webp',
    tag: { en: 'Daily remembrances, offline.', fr: 'Les adhkar du quotidien, hors ligne.', ar: 'أذكار يومية، دون اتصال.' } },
  { id: 'nexnum', name: 'NexNum', cat: 'games', live: true, page: '/nexnum/', localized: false,
    shot: '/nexnum/img/play.webp', icon: '/nexnum/img/icon-256.webp',
    tag: { en: 'Higher or lower, played bold.', fr: 'Plus ou moins, en version audacieuse.', ar: 'أعلى أم أدنى، بجرأة.' } },
  { id: 'chess360', name: 'Chess360', cat: 'games', mono: 'C', color: '#3b82f6',
    tag: { en: 'Premium chess, offline against a strong engine.', fr: 'Les échecs premium, hors ligne face à un moteur redoutable.', ar: 'شطرنج راقٍ، دون اتصال أمام محرك قوي.' } },
  { id: 'wuzzle', name: 'Wuzzle', cat: 'games', icon: '/assets/img/apps/wuzzle.webp', color: '#8b5cf6',
    tag: { en: 'Crack the hidden word from a clue.', fr: 'Trouvez le mot caché grâce à un indice.', ar: 'اكتشف الكلمة المخفية من خلال تلميح.' } },
  { id: 'calo360', name: 'Calo360', cat: 'health', icon: '/assets/img/apps/calo360.webp', color: '#34d399',
    tag: { en: 'Calories, macros and habits, simply.', fr: 'Calories, macros et habitudes, simplement.', ar: 'السعرات والعناصر الغذائية والعادات، ببساطة.' } },
  { id: 'scanfly360', name: 'ScanFly360', cat: 'tools', mono: 'S', color: '#38bdf8',
    tag: { en: 'Scan, organize and share documents, offline.', fr: 'Scannez, rangez et partagez vos documents, hors ligne.', ar: 'امسح مستنداتك ونظّمها وشاركها، دون اتصال.' } },
  { id: 'safe180', name: 'Safe180', cat: 'family', icon: '/assets/img/apps/safe180.webp', color: '#22d3ee',
    tag: { en: 'Stay close. Stay safe.', fr: 'Restez proches, restez en sécurité.', ar: 'ابقَ قريبًا، ابقَ آمنًا.' } },
  { id: 'lovivup', name: 'Lovivup', cat: 'love', icon: '/assets/img/apps/lovivup.webp', color: '#ec4899',
    tag: { en: 'Your next connection starts here.', fr: 'Votre prochaine rencontre commence ici.', ar: 'تعارفك القادم يبدأ من هنا.' } },
  { id: 'twinove', name: 'Twinove', cat: 'love', icon: '/assets/img/apps/twinove.webp', color: '#c084fc',
    tag: { en: 'Two hearts. One story.', fr: 'Deux cœurs. Une histoire.', ar: 'قلبان. قصة واحدة.' } },
  { id: 'duovie', name: 'Duovie', cat: 'finance', icon: '/assets/img/apps/duovie.webp', color: '#f97316',
    tag: { en: 'Shared budgets for couples and households.', fr: 'Le budget partagé du couple et du foyer.', ar: 'ميزانية مشتركة للزوجين والأسرة.' } },
];

const T = {
  en: { title: 'All apps', count: (l, s) => `${l} available · ${s} in the studio`, soon: 'Coming soon', filters: 'Categories' },
  fr: { title: 'Toutes les apps', count: (l, s) => `${l} disponibles · ${s} en préparation`, soon: 'Bientôt', filters: 'Catégories' },
  ar: { title: 'كل التطبيقات', count: (l, s) => `${l} متاحة · ${s} قيد التطوير`, soon: 'قريبًا', filters: 'التصنيفات' },
};

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
const catName = (id, L) => CATEGORIES.find((c) => c.id === id)[L];

function block(L) {
  const t = T[L];
  const live = APPS.filter((a) => a.live).length;
  const used = CATEGORIES.filter((c) => c.id === 'all' || APPS.some((a) => a.cat === c.id));
  const I = '          ';
  const out = [];
  out.push(`${I}<!-- catalog:start (generated by tools/catalog.js) -->`);
  out.push(`${I}<div class="row-head reveal" style="margin-top: clamp(56px, 7vw, 96px)">`);
  out.push(`${I}  <h2>${t.title}</h2>`);
  out.push(`${I}  <p>${t.count(live, APPS.length - live)}</p>`);
  out.push(`${I}</div>`);
  out.push(`${I}<div class="cat-filter reveal" role="group" aria-label="${t.filters}">`);
  for (const c of used) {
    const n = c.id === 'all' ? APPS.length : APPS.filter((a) => a.cat === c.id).length;
    out.push(`${I}  <button type="button" class="cat-btn" data-filter="${c.id}" aria-pressed="${c.id === 'all'}">${esc(c[L])}<span class="n">${n}</span></button>`);
  }
  out.push(`${I}</div>`);
  out.push(`${I}<div class="catalog reveal">`);
  for (const a of APPS) {
    const cat = `<span class="cat-label">${esc(catName(a.cat, L))}</span>`;
    if (a.live) {
      const href = L !== 'en' && a.localized ? `/${L}${a.page}` : a.page;
      out.push(`${I}  <a class="poster" href="${href}" data-app="${a.id}" data-cat="${a.cat}">`);
      out.push(`${I}    <img src="${a.shot}" alt="" width="390" height="844" loading="lazy" />`);
      out.push(`${I}    <div class="info">`);
      out.push(`${I}      ${cat}`);
      out.push(`${I}      <img class="icon" src="${a.icon}" width="44" height="44" alt="" />`);
      out.push(`${I}      <h3>${esc(a.name)}</h3>`);
      out.push(`${I}      <p>${esc(a.tag[L])}</p>`);
      out.push(`${I}    </div>`);
      out.push(`${I}  </a>`);
    } else {
      const icon = a.icon
        ? `<img class="app-icon" src="${a.icon}" width="88" height="88" alt="" loading="lazy" />`
        : `<span class="app-icon mono" aria-hidden="true">${esc(a.mono)}</span>`;
      out.push(`${I}  <div class="poster upcoming" data-cat="${a.cat}" style="--glow: ${a.color}">`);
      out.push(`${I}    ${icon}`);
      out.push(`${I}    <div class="info">`);
      out.push(`${I}      ${cat}`);
      out.push(`${I}      <h3>${esc(a.name)}</h3>`);
      out.push(`${I}      <p>${esc(a.tag[L])}</p>`);
      out.push(`${I}      <span class="chip">${t.soon}</span>`);
      out.push(`${I}    </div>`);
      out.push(`${I}  </div>`);
    }
  }
  out.push(`${I}</div>`);
  out.push(`${I}<!-- catalog:end -->`);
  return out.join('\n');
}

for (const L of ['en', 'fr', 'ar']) {
  const f = path.join(ROOT, L === 'en' ? '' : L, 'index.html');
  const raw = fs.readFileSync(f, 'utf8');
  const crlf = raw.includes('\r\n');
  let s = raw.replace(/\r\n/g, '\n');
  const marked = /[ \t]*<!-- catalog:start[\s\S]*?<!-- catalog:end -->/;
  // First run: replace the hand-written "All apps" row-head + posters block.
  const legacy = /[ \t]*<div class="row-head reveal" style="margin-top: clamp\(56px[\s\S]*?<div class="posters reveal">[\s\S]*?\n {10}<\/div>(?=\n {8}<\/div>\n {6}<\/section>)/;
  if (marked.test(s)) s = s.replace(marked, () => block(L));
  else if (legacy.test(s)) s = s.replace(legacy, () => block(L));
  else throw new Error('catalogue block not found in ' + f);
  fs.writeFileSync(f, crlf ? s.replace(/\n/g, '\r\n') : s);
  console.log('updated', path.relative(ROOT, f));
}
